require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?>
<main class="content"><style>.panel{background:#fff;padding:20px;border-radius:12px;box-shadow:0 1px 4px #0001;margin-bottom:18px}.staff-form{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:5px}.field input,.field select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #dbe3ec;border-radius:7px}.btn{background:#174a7e;color:#fff;border:0;border-radius:7px;padding:10px 14px;font-weight:700;cursor:pointer}.flash{padding:12px;background:#ecfdf5;color:#166534;border-radius:8px;margin:12px 0}.table{width:100%;border-collapse:collapse}.table th{background:#174a7e;color:#fff;padding:10px;text-align:left}.table td{padding:10px;border-bottom:1px solid #e5eaf0;font-size:13px}@media(max-width:900px){.staff-form{grid-template-columns:1fr}}</style>
<h1>Staff Management</h1><p>Maintain employee profiles separately from system login accounts.</p><?php if($flash):?><div class="flash"><?=e($flash)?></div><?php endif;?>
<?php if(hasModulePermission('staff','create')): ?><div class="panel"><h3>Add Staff Member</h3><form method="post" action="store.php" class="staff-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="field"><label>Full Name *</label><input name="full_name" required maxlength="160"></div><div class="field"><label>Phone</label><input name="phone" maxlength="30"></div><div class="field"><label>Email</label><input type="email" name="email" maxlength="160"></div><div class="field"><label>Department</label><input name="department" maxlength="100" placeholder="Sales, Store, Accounts..."></div><div class="field"><label>Job Title</label><input name="job_title" maxlength="100"></div><div class="field"><label>Employment Type</label><select name="employment_type"><option>Full-time</option><option>Part-time</option><option>Casual</option><option>Contract</option></select></div><div class="field"><label>Hire Date</label><input type="date" name="hire_date"></div><div class="field"><label>Status</label><select name="status"><option>Active</option><option>Inactive</option><option>Terminated</option></select></div><div class="field"><label>Notes</label><input name="notes" maxlength="1000"></div><div><button class="btn">Save Staff Profile</button></div></form></div><?php endif; ?>
<div class="panel" style="overflow:auto"><h3>Staff Directory</h3><table class="table"><thead><tr><th>Employee No.</th><th>Name</th><th>Department / Title</th><th>Phone</th><th>Employment</th><th>Login Account</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($staff as $s):?><tr><td><?=e($s['employee_number'])?></td><td><strong><?=e($s['full_name'])?></strong></td><td><?=e(trim(($s['department']??'').' / '.($s['job_title']??''),' /'))?></td><td><?=e($s['phone']??'')?></td><td><?=e($s['employment_type'])?></td><td><?=e($s['username']??'Not linked')?></td><td><?=e($s['status'])?></td><td><?php if(hasModulePermission('staff','edit')):?><a class="btn" href="edit.php?id=<?=(int)$s['id']?>">Manage</a><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$staff):?><tr><td colspan="8">No staff records yet.</td></tr><?php endif;?></tbody></table></div></main><?php require_once __DIR__.'/../../includes/footer.php';?>